import { createSlice } from '@reduxjs/toolkit';

// Define the initial state for settings
const initialState = {
  theme: 'light',
  language: 'en',
  // Add other settings-related properties as needed
};

// Create the settings slice
const settingSlice = createSlice({
  name: 'settings',
  initialState,
  reducers: {
    setTheme: (state, action) => {
      state.theme = action.payload;
    },
    setLanguage: (state, action) => {
      state.language = action.payload;
    },
    // Add other reducer actions as needed for settings
  },
});

// Export the action creators generated by createSlice
export const { setTheme, setLanguage } = settingSlice.actions;

// Export the settings reducer
export default settingSlice.reducer;
